"use client";

import * as React from "react";
import { RiyalInput } from "riyal/react";
import { cn } from "@/lib/utils";

export interface RiyalAmountInputProps {
	value: number | "";
	onValueChange: (value: number) => void;
	label?: string;
	hint?: string;
	error?: string;
	locale?: string;
	decimals?: number;
	mask?: boolean;
	allowNegative?: boolean;
	placeholder?: string;
	disabled?: boolean;
	id?: string;
	className?: string;
}

export function RiyalAmountInput({
	value,
	onValueChange,
	label,
	hint,
	error,
	locale,
	decimals,
	mask = true,
	allowNegative = false,
	placeholder = "0.00",
	disabled,
	id,
	className,
}: RiyalAmountInputProps) {
	const generatedId = React.useId();
	const inputId = id ?? generatedId;
	const describedBy = error ? `${inputId}-error` : hint ? `${inputId}-hint` : undefined;

	return (
		<div className={cn("flex flex-col gap-1.5", className)}>
			{label ? (
				<label
					htmlFor={inputId}
					className="text-sm font-medium text-foreground data-[disabled=true]:opacity-60"
					data-disabled={disabled || undefined}
				>
					{label}
				</label>
			) : null}
			<RiyalInput
				id={inputId}
				value={value}
				onValueChange={onValueChange}
				locale={locale}
				decimals={decimals}
				mask={mask}
				allowNegative={allowNegative}
				placeholder={placeholder}
				disabled={disabled}
				aria-invalid={Boolean(error) || undefined}
				aria-describedby={describedBy}
				className={cn(
					"h-10 rounded-md border border-input bg-background px-3 text-sm text-foreground transition-colors",
					"focus-within:border-ring focus-within:ring-1 focus-within:ring-ring",
					"[&_input]:flex-1 [&_input]:min-w-0 [&_input]:bg-transparent [&_input]:outline-none [&_input]:placeholder:text-muted-foreground",
					"[&_input]:disabled:opacity-60",
					error &&
						"border-destructive focus-within:border-destructive focus-within:ring-destructive",
				)}
			/>
			{error ? (
				<p id={`${inputId}-error`} className="text-xs text-destructive">
					{error}
				</p>
			) : hint ? (
				<p id={`${inputId}-hint`} className="text-xs text-muted-foreground">
					{hint}
				</p>
			) : null}
		</div>
	);
}
